/*
 * Generated by the offline plugin in vite.config.ts. Do not edit dist/sw.js.
 *
 * The app ships its compendium snapshot, so precaching the build makes the
 * whole tool work with no network: the shell, the hashed assets, the data
 * chunks and the rule documents hover previews read.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const CACHE_PREFIX = "malice-menagerie-";
const CACHE_NAME = `${CACHE_PREFIX}${VERSION}`;
const PRECACHE_URLS = new Set(PRECACHE.map(({ url }) => new URL(url, self.location.origin).href));

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const existing = new Set((await cache.keys()).map(({ url }) => url));
      const missing = PRECACHE.filter(
        ({ url }) => !existing.has(new URL(url, self.location.origin).href),
      );
      // addAll commits as a batch. A rollback can target the cache still in
      // use by the active worker, so an install must never delete that cache.
      // Integrity also rejects a different deployment's bytes or a 200 SPA fallback.
      await cache.addAll(
        missing.map(
          ({ url, integrity }) =>
            new Request(new URL(url, self.location.origin), {
              cache: url.startsWith("/assets/") ? "default" : "reload",
              redirect: "error",
              integrity,
            }),
        ),
      );
      // No skipWaiting: an open tab stays on the build it loaded, so its
      // already-cached lazy chunks remain available until it closes.
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Activation only runs once no client is controlled by an older
      // worker, so removing old caches cannot break an open tab.
      const keys = await caches.keys();
      const stale = keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME);
      await Promise.all(stale.map((key) => caches.delete(key)));
      // Enable offline on the first visit. Exact URLs for scripts and data
      // keep an already-loaded page from reading another snapshot.
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // The Owlbear extension and its worker are updated independently and must
  // never be served from this cache.
  if (
    url.pathname === "/obr" ||
    url.pathname.startsWith("/obr/") ||
    url.pathname === "/pairing-worker.js"
  )
    return;

  // Match static assets first even when opened as documents. The app's
  // extensionless routes share the root shell, and /index.html is its alias.
  let cacheKey = url.href;
  if (!PRECACHE_URLS.has(cacheKey)) {
    const appRoute =
      url.pathname === "/index.html" ||
      (!/^\/(?:assets|data)(?:\/|$)/.test(url.pathname) && !/\.[^/]+\/?$/.test(url.pathname));
    if (request.mode !== "navigate" || !appRoute) return;
    cacheKey = "/";
  }

  // Scope reads to this build, even while a newer worker is precaching.
  // The static host varies on Origin, which can differ from the install request.
  const matchOptions = { cacheName: CACHE_NAME, ignoreVary: true };
  event.respondWith(
    (async () => {
      const cached = await caches.match(cacheKey, matchOptions).catch(() => undefined);
      // A miss can still work online. Network bytes may be from another build,
      // so keep them out of the verified precache.
      return cached ?? fetch(request);
    })(),
  );
});
